44	export function DashboardTaskSlider() {
45	  const queryClient = useQueryClient();
46	  const { data: rawItems, isLoading } = useGetOverdueItems();
47	  const updateTask = useUpdateTask();
48	  const updateEblast = useUpdateEblast();
49	
50	  const [index, setIndex] = useState(0);
51	  const [noteDrafts, setNoteDrafts] = useState<Record<string, string>>({});
52	  const [savedFlash, setSavedFlash] = useState<Record<string, boolean>>({});
53	  const [completing, setCompleting] = useState<Record<string, boolean>>({});
54	  const [noteOpen, setNoteOpen] = useState<Record<string, boolean>>({});
55	
56	  // Pomodoro state
57	  const intervalRef = useRef<ReturnType<typeof setInterval> | null>(null);
58	  const [pomodoroOpen, setPomodoroOpen] = useState(false);
59	  const [presets, setPresets] = useState<[number, number, number]>([2, 5, 30]);
60	  const [selectedPreset, setSelectedPreset] = useState<0 | 1 | 2 | null>(null);
61	  const [timeLeft, setTimeLeft] = useState(0);
62	  const [isRunning, setIsRunning] = useState(false);
63	  const [timesUp, setTimesUp] = useState(false);
64	
65	  const items = useMemo(() => {
66	    if (!rawItems) return [];
67	    const dueToday = rawItems.filter(i => i.daysOverdue === 0);
68	    const overdue = rawItems
69	      .filter(i => i.daysOverdue > 0)
70	      .sort((a, b) => b.daysOverdue - a.daysOverdue);
71	    return [...dueToday, ...overdue];
72	  }, [rawItems]);
73	
74	  // Seed note drafts when items load
75	  useEffect(() => {
76	    if (!items.length) return;
77	    setNoteDrafts(prev => {
78	      const next = { ...prev };
79	      for (const item of items) {
80	        const k = itemKey(item.type, item.id);
81	        if (!(k in next)) next[k] = item.notes ?? "";
82	      }
83	      return next;
84	    });
85	  }, [items]);
86	
87	  // Countdown ticker
88	  useEffect(() => {
89	    if (!isRunning) return;
90	    intervalRef.current = setInterval(() => {
91	      setTimeLeft(t => {
92	        if (t <= 1) {
93	          clearInterval(intervalRef.current!);
94	          setIsRunning(false);
95	          setTimesUp(true);
96	          return 0;
97	        }
98	        return t - 1;
99	      });
100	    }, 1000);
101	    return () => clearInterval(intervalRef.current!);
102	  }, [isRunning]);
103	
104	  // Close pomodoro when navigating to a different card
105	  useEffect(() => {
106	    clearInterval(intervalRef.current!);
107	    setPomodoroOpen(false);
108	    setSelectedPreset(null);
109	    setTimeLeft(0);
110	    setIsRunning(false);
111	    setTimesUp(false);
112	  }, [index]);
113	
114	  const invalidate = () => {
115	    queryClient.invalidateQueries({ queryKey: getGetOverdueItemsQueryKey() });
116	    queryClient.invalidateQueries({ queryKey: getGetDashboardSummaryQueryKey() });
117	  };
118	
119	  if (isLoading) return <Skeleton className="w-full h-40 rounded-lg" />;
120	  if (items.length === 0) return null;
121	
122	  const safeIndex = Math.min(index, items.length - 1);
123	  const item = items[safeIndex];
124	  const isToday = item.daysOverdue === 0;
125	  const total = items.length;
126	  const key = itemKey(item.type, item.id);
127	  const currentNote = noteDrafts[key] ?? item.notes ?? "";
128	  const isCompleting = completing[key] ?? false;
129	  const isNoteOpen = noteOpen[key] ?? false;
130	  const accentText = isToday ? "text-amber-400" : "text-red-400";
131	
132	  // ── Navigation ────────────────────────────────────────────────────────────
133	  const prev = () => setIndex(i => Math.max(0, i - 1));
134	  const next = () => setIndex(i => Math.min(total - 1, i + 1));
135	
136	  // ── Notes ─────────────────────────────────────────────────────────────────
137	  const saveNote = () => {
138	    const draft = currentNote;
139	    const original = item.notes ?? "";
140	    if (draft === original) return;
141	    if (item.type === "task") {
142	      updateTask.mutate(
143	        { showId: item.showId, taskId: item.id, data: { notes: draft || null } },
144	        { onSuccess: () => {
145	            setSavedFlash(p => ({ ...p, [key]: true }));
146	            setTimeout(() => setSavedFlash(p => ({ ...p, [key]: false })), 1500);
147	            invalidate();
148	          }
149	        }
150	      );
151	    } else {
152	      updateEblast.mutate(
153	        { showId: item.showId, eblastId: item.id, data: { notes: draft || null } },
154	        { onSuccess: () => {
155	            setSavedFlash(p => ({ ...p, [key]: true }));
156	            setTimeout(() => setSavedFlash(p => ({ ...p, [key]: false })), 1500);
157	            invalidate();
158	          }
159	        }
160	      );
161	    }
162	  };
163	
164	  const openNote = () => setNoteOpen(p => ({ ...p, [key]: true }));
165	  const closeNote = () => {
166	    saveNote();
167	    setNoteOpen(p => ({ ...p, [key]: false }));
168	  };
169	
170	  // ── Complete / Sent ───────────────────────────────────────────────────────
171	  const markComplete = () => {
172	    setCompleting(p => ({ ...p, [key]: true }));
173	    const now = new Date().toISOString();
174	    if (item.type === "task") {
175	      updateTask.mutate(
176	        { showId: item.showId, taskId: item.id, data: { completed: true, completedAt: now } },
177	        {
178	          onSuccess: () => {
179	            invalidate();
180	            setIndex(i => Math.max(0, Math.min(i, total - 2)));
181	            setCompleting(p => ({ ...p, [key]: false }));
182	          },
183	          onError: () => setCompleting(p => ({ ...p, [key]: false })),
184	        }
185	      );
186	    } else {
187	      updateEblast.mutate(
188	        { showId: item.showId, eblastId: item.id, data: { sent: true, sentAt: now } },
189	        {
190	          onSuccess: () => {
191	            invalidate();
192	            setIndex(i => Math.max(0, Math.min(i, total - 2)));
193	            setCompleting(p => ({ ...p, [key]: false }));
194	          },
195	          onError: () => setCompleting(p => ({ ...p, [key]: false })),
196	        }
197	      );
198	    }
199	  };
200	
201	  // ── Pomodoro helpers ──────────────────────────────────────────────────────
202	  const openPomodoro = () => setPomodoroOpen(true);
203	
204	  const closePomodoro = () => {
205	    clearInterval(intervalRef.current!);
206	    setPomodoroOpen(false);
207	    setSelectedPreset(null);
208	    setTimeLeft(0);
209	    setIsRunning(false);
210	    setTimesUp(false);
211	  };
212	
213	  const selectPreset = (i: 0 | 1 | 2) => {
214	    clearInterval(intervalRef.current!);
215	    setIsRunning(false);
216	    setTimesUp(false);
217	    setSelectedPreset(i);
218	    setTimeLeft(presets[i] * 60);
219	  };
220	
221	  const adjustPreset = (i: 0 | 1 | 2, delta: number) => {
222	    setPresets(p => {
223	      const next: [number, number, number] = [...p] as [number, number, number];
224	      next[i] = Math.max(1, next[i] + delta);
225	      if (selectedPreset === i) {
226	        clearInterval(intervalRef.current!);
227	        setIsRunning(false);
228	        setTimesUp(false);
229	        setTimeLeft(next[i] * 60);
230	      }
231	      return next;
232	    });
233	  };
234	
235	  const toggleTimer = () => {
236	    if (selectedPreset === null) return;
237	    if (timeLeft === 0) {
238	      setTimeLeft(presets[selectedPreset] * 60);
239	      setTimesUp(false);
240	    }
241	    setIsRunning(r => !r);
242	  };
243	
244	  const resetTimer = () => {
245	    clearInterval(intervalRef.current!);
246	    setIsRunning(false);
247	    setTimesUp(false);
248	    if (selectedPreset !== null) setTimeLeft(presets[selectedPreset] * 60);
249	  };
250	
251	  const showTab = item.type === "eblast" ? "eblasts" : "tasks";
252	  const completionLabel = item.type === "eblast" ? "Mark Sent" : "Mark Complete";
253	  const cardBg = isToday ? "bg-amber-500/5 border-amber-500/20" : "bg-red-500/5 border-red-500/20";
254	
255	  // ── Pomodoro view ─────────────────────────────────────────────────────────
256	  if (pomodoroOpen) {
257	    return (
258	      <div className={`rounded-lg border p-5 flex flex-col gap-5 ${cardBg}`}>
259	        {/* Back button */}
260	        <button
261	          onClick={closePomodoro}
262	          className="flex items-center gap-1 text-xs text-muted-foreground hover:text-foreground transition-colors w-fit"
263	        >
264	          <ArrowLeft className="h-3.5 w-3.5" />
265	          Back
266	        </button>
267	
268	        {/* Centered task info */}
269	        <div className="flex flex-col items-center gap-1.5 text-center">
270	          <span className={`text-[10px] font-medium px-1.5 py-0.5 rounded border ${chipClass(item.type, item.category)}`}>
271	            {item.type === "eblast" ? "E-Blast" : (item.category ?? "Task")}
272	          </span>
273	          <p className="text-xl font-bold leading-tight">{item.name}</p>
274	          <p className="text-sm text-muted-foreground">
275	            {item.showName}
276	            <span className="mx-1.5 opacity-40">•</span>
277	            Due {formatDate(item.dueDate)}
278	          </p>
279	        </div>
280	
281	        {/* Timer display */}
282	        <div className="flex flex-col items-center gap-1">
283	          <span className={`text-6xl font-black tabular-nums tracking-tight ${selectedPreset !== null ? accentText : "text-muted-foreground/40"}`}>
284	            {selectedPreset !== null ? formatTime(timeLeft) : "--:--"}
285	          </span>
286	          {timesUp && (
287	            <span className={`text-xs font-semibold ${accentText}`}>Time's up!</span>
288	          )}
289	        </div>
290	
291	        {/* Preset buttons */}
292	        <div className="flex items-center justify-center gap-3">
293	          {([0, 1, 2] as const).map(i => {
294	            const isSelected = selectedPreset === i;
295	            return (
296	              <div key={i} className="flex items-center gap-1">
297	                <Button
298	                  variant="ghost"
299	                  size="icon"
300	                  className="h-6 w-6"
301	                  onClick={() => adjustPreset(i, -1)}
302	                  disabled={presets[i] <= 1}
303	                >
304	                  <span className="text-sm leading-none">−</span>
305	                </Button>
306	                <button
307	                  onClick={() => selectPreset(i)}
308	                  className={`px-3 py-1.5 rounded-md text-sm font-medium border transition-colors ${
309	                    isSelected
310	                      ? "bg-primary/15 border-primary/40 text-primary"
311	                      : "border-border text-muted-foreground hover:text-foreground hover:border-muted-foreground"
312	                  }`}
313	                >
314	                  {presets[i]} min
315	                </button>
316	                <Button
317	                  variant="ghost"
318	                  size="icon"
319	                  className="h-6 w-6"
320	                  onClick={() => adjustPreset(i, 1)}
321	                >
322	                  <span className="text-sm leading-none">+</span>
323	                </Button>
324	              </div>
325	            );
326	          })}
327	        </div>
328	
329	        {/* Start / Pause + Reset */}
330	        <div className="flex items-center justify-center gap-3">
331	          <Button
332	            size="sm"
333	            className="gap-1.5 min-w-[100px]"
334	            onClick={toggleTimer}
335	            disabled={selectedPreset === null}
336	          >
337	            {isRunning
338	              ? <><Pause className="h-3.5 w-3.5" /> Pause</>
339	              : <><Play className="h-3.5 w-3.5" /> Start</>
340	            }
341	          </Button>
342	          <Button
343	            variant="ghost"
344	            size="sm"
345	            className="gap-1.5"
346	            onClick={resetTimer}
347	            disabled={selectedPreset === null}
348	          >
349	            <RotateCcw className="h-3.5 w-3.5" />
350	            Reset
351	          </Button>
352	        </div>
353	      </div>
354	    );
355	  }
356	
357	  // ── Default slider view ───────────────────────────────────────────────────
358	  return (
359	    <div
360	      className={`rounded-lg border p-5 flex flex-col gap-4 transition-opacity duration-300 ${isCompleting ? "opacity-40 pointer-events-none" : ""} ${cardBg}`}
361	    >
362	      {/* Header: urgency label + counter + arrows */}
363	      <div className="flex items-center justify-between gap-3">
364	        <span className={`text-xs font-bold uppercase tracking-widest ${accentText}`}>
365	          {isToday ? "Due Today" : `${item.daysOverdue} ${item.daysOverdue === 1 ? "day" : "days"} overdue`}
366	        </span>
367	        <div className="flex items-center gap-2">
368	          <span className="text-xs text-muted-foreground tabular-nums">{safeIndex + 1} / {total}</span>
369	          <Button variant="ghost" size="icon" className="h-7 w-7" onClick={prev} disabled={safeIndex === 0}>
370	            <ChevronLeft className="h-4 w-4" />
371	          </Button>
372	          <Button variant="ghost" size="icon" className="h-7 w-7" onClick={next} disabled={safeIndex === total - 1}>
373	            <ChevronRight className="h-4 w-4" />
374	          </Button>
375	        </div>
376	      </div>
377	
378	      {/* Task info */}
379	      <div className="flex items-start justify-between gap-4">
380	        <div className="flex flex-col gap-1.5 min-w-0">
381	          <div className="flex items-center gap-1.5 flex-wrap">
382	            <span className={`text-[10px] font-medium px-1.5 py-0.5 rounded border ${chipClass(item.type, item.category)}`}>
383	              {item.type === "eblast" ? "E-Blast" : (item.category ?? "Task")}
384	            </span>
385	          </div>
386	          <p className="text-lg font-semibold leading-tight">{item.name}</p>
387	          <p className="text-sm text-muted-foreground">
388	            {item.showName}
389	            <span className="mx-1.5 opacity-40">•</span>
390	            Due {formatDate(item.dueDate)}
391	          </p>
392	        </div>
393	
394	        <Link href={`/shows/${item.showId}?tab=${showTab}`} className="shrink-0">
395	          <Button variant="outline" size="sm">Open</Button>
396	        </Link>
397	      </div>
398	
399	      {/* Note — compact single line, expands on click */}
400	      {!isNoteOpen ? (
401	        <button
402	          onClick={openNote}
403	          className="flex items-center gap-1.5 w-full text-left text-sm text-muted-foreground hover:text-foreground transition-colors group"
404	        >
405	          <ChevronDown className="h-3.5 w-3.5 shrink-0 opacity-50 group-hover:opacity-80" />
406	          <span className="truncate">{currentNote || "Add a note…"}</span>
407	        </button>
408	      ) : (
409	        <div className="flex flex-col gap-1">
410	          <Textarea
411	            key={key}
412	            autoFocus
413	            value={currentNote}
414	            onChange={e => setNoteDrafts(p => ({ ...p, [key]: e.target.value }))}
415	            onBlur={closeNote}
416	            placeholder="Add a note…"
417	            className="resize-none text-sm min-h-[64px]"
418	            rows={2}
419	          />
420	          {savedFlash[key] && (
421	            <span className="text-xs text-muted-foreground">Saved</span>
422	          )}
423	        </div>
424	      )}
425	
426	      {/* Actions */}
427	      <div className="flex items-center justify-between gap-3">
428	        <div className="flex items-center gap-2">
429	          <Button
430	            variant="default"
431	            size="sm"
432	            className="gap-1.5"
433	            onClick={markComplete}
434	            disabled={isCompleting}
435	          >
436	            <Check className="h-3.5 w-3.5" />
437	            {completionLabel}
438	          </Button>
439	          <Button variant="ghost" size="icon" className="h-8 w-8" onClick={openPomodoro} title="Focus timer">
440	            <Timer className="h-4 w-4" />
441	          </Button>
442	        </div>
443	
444	        {/* Dot indicators */}
445	        {total > 1 && total <= 10 && (
446	          <div className="flex items-center gap-1">
447	            {items.map((_, i) => (
448	              <button
449	                key={i}
450	                onClick={() => setIndex(i)}
451	                className={`rounded-full transition-all ${
452	                  i === safeIndex
453	                    ? `h-1.5 w-4 ${isToday ? "bg-amber-400" : "bg-red-400"}`
454	                    : "h-1.5 w-1.5 bg-muted-foreground/30 hover:bg-muted-foreground/50"
455	                }`}
456	              />
457	            ))}
458	          </div>
459	        )}
460	      </div>
461	    </div>
462	  );
463	}
