44	export function DashboardTaskSlider() {
45	  const queryClient = useQueryClient();
46	  const { data: rawItems, isLoading } = useGetOverdueItems();
47	  const updateTask = useUpdateTask();
48	  const updateEblast = useUpdateEblast();
49	
50	  const [index, setIndex] = useState(0);
51	  const [noteDrafts, setNoteDrafts] = useState<Record<string, string>>({});
52	  const [savedFlash, setSavedFlash] = useState<Record<string, boolean>>({});
53	  const [completing, setCompleting] = useState<Record<string, boolean>>({});
54	  const [noteOpen, setNoteOpen] = useState<Record<string, boolean>>({});
55	
56	  // Pomodoro state
57	  const intervalRef = useRef<ReturnType<typeof setInterval> | null>(null);
58	  const [pomodoroOpen, setPomodoroOpen] = useState(false);
59	  const [presets, setPresets] = useState<[number, number, number]>([2, 5, 30]);
60	  const [selectedPreset, setSelectedPreset] = useState<0 | 1 | 2 | null>(null);
61	  const [timeLeft, setTimeLeft] = useState(0);
62	  const [isRunning, setIsRunning] = useState(false);
63	  const [timesUp, setTimesUp] = useState(false);
64	
65	  const items = useMemo(() => {
66	    if (!rawItems) return [];
67	    const dueToday = rawItems.filter(i => i.daysOverdue === 0);
68	    const overdue = rawItems
69	      .filter(i => i.daysOverdue > 0)
70	      .sort((a, b) => b.daysOverdue - a.daysOverdue);
71	    return [...dueToday, ...overdue];
72	  }, [rawItems]);
73	
74	  // Seed note drafts when items load
75	  useEffect(() => {
76	    if (!items.length) return;
77	    setNoteDrafts(prev => {
78	      const next = { ...prev };
79	      for (const item of items) {
80	        const k = itemKey(item.type, item.id);
81	        if (!(k in next)) next[k] = item.notes ?? "";
82	      }
83	      return next;
84	    });
85	  }, [items]);
86	
87	  // Countdown ticker
88	  useEffect(() => {
89	    if (!isRunning) return;
90	    intervalRef.current = setInterval(() => {
91	      setTimeLeft(t => {
92	        if (t <= 1) {
93	          clearInterval(intervalRef.current!);
94	          setIsRunning(false);
95	          setTimesUp(true);
96	          return 0;
97	        }
98	        return t - 1;
99	      });
100	    }, 1000);
101	    return () => clearInterval(intervalRef.current!);
102	  }, [isRunning]);
103	
104	  // Close pomodoro when navigating to a different card
105	  useEffect(() => {
106	    clearInterval(intervalRef.current!);
107	    setPomodoroOpen(false);
108	    setSelectedPreset(null);
109	    setTimeLeft(0);
110	    setIsRunning(false);
111	    setTimesUp(false);
112	  }, [index]);
113	
114	  const invalidate = () => {
115	    queryClient.invalidateQueries({ queryKey: getGetOverdueItemsQueryKey() });
116	    queryClient.invalidateQueries({ queryKey: getGetDashboardSummaryQueryKey() });
117	  };
118	
119	  if (isLoading) return <Skeleton className="w-full h-40 rounded-lg" />;
120	  if (items.length === 0) return null;
121	
122	  const safeIndex = Math.min(index, items.length - 1);
123	  const item = items[safeIndex];
124	  const isToday = item.daysOverdue === 0;
125	  const total = items.length;
126	  const key = itemKey(item.type, item.id);
127	  const currentNote = noteDrafts[key] ?? item.notes ?? "";
128	  const isCompleting = completing[key] ?? false;
129	  const isNoteOpen = noteOpen[key] ?? false;
130	  const accentText = isToday ? "text-amber-400" : "text-red-400";
131	
132	  // ── Navigation ────────────────────────────────────────────────────────────
133	  const prev = () => setIndex(i => Math.max(0, i - 1));
134	  const next = () => setIndex(i => Math.min(total - 1, i + 1));
135	
136	  // ── Notes ─────────────────────────────────────────────────────────────────
137	  const saveNote = () => {
138	    const draft = currentNote;
139	    const original = item.notes ?? "";
140	    if (draft === original) return;
141	    if (item.type === "task") {
142	      updateTask.mutate(
143	        { showId: item.showId, taskId: item.id, data: { notes: draft || null } },
144	        { onSuccess: () => {
145	            setSavedFlash(p => ({ ...p, [key]: true }));
146	            setTimeout(() => setSavedFlash(p => ({ ...p, [key]: false })), 1500);
147	            invalidate();
148	          }
149	        }
150	      );
151	    } else {
152	      updateEblast.mutate(
153	        { showId: item.showId, eblastId: item.id, data: { notes: draft || null } },
154	        { onSuccess: () => {
155	            setSavedFlash(p => ({ ...p, [key]: true }));
156	            setTimeout(() => setSavedFlash(p => ({ ...p, [key]: false })), 1500);
157	            invalidate();
158	          }
159	        }
160	      );
161	    }
162	  };
163	
164	  const openNote = () => setNoteOpen(p => ({ ...p, [key]: true }));
165	  const closeNote = () => {
166	    saveNote();
167	    setNoteOpen(p => ({ ...p, [key]: false }));
168	  };
169	
170	  // ── Complete / Sent ───────────────────────────────────────────────────────
171	  const markComplete = () => {
172	    setCompleting(p => ({ ...p, [key]: true }));
173	    const now = new Date().toISOString();
174	    if (item.type === "task") {
175	      updateTask.mutate(
176	        { showId: item.showId, taskId: item.id, data: { completed: true, completedAt: now } },
177	        {
178	          onSuccess: () => {
179	            invalidate();
180	            setIndex(i => Math.max(0, Math.min(i, total - 2)));
181	            setCompleting(p => ({ ...p, [key]: false }));
182	          },
183	          onError: () => setCompleting(p => ({ ...p, [key]: false })),
184	        }
