193	            setCompleting(p => ({ ...p, [key]: false }));
194	          },
195	          onError: () => setCompleting(p => ({ ...p, [key]: false })),
196	        }
197	      );
198	    }
199	  };
200	
201	  // ── Pomodoro helpers ──────────────────────────────────────────────────────
202	  const openPomodoro = () => setPomodoroOpen(true);
203	
204	  const closePomodoro = () => {
205	    clearInterval(intervalRef.current!);
