397	function TaskRow({ task, showId, onToggle, onDelete }: { task: any, showId: number, onToggle: () => void, onDelete: () => void }) {
398	  const [expanded, setExpanded] = useState(false);
399	  const [editOpen, setEditOpen] = useState(false);
400	  const [datePickerOpen, setDatePickerOpen] = useState(false);
401	  const [justCompleted, setJustCompleted] = useState(false);
402	
403	  const handleToggle = () => {
404	    if (!task.completed) {
405	      setJustCompleted(true);
406	      setTimeout(() => setJustCompleted(false), 650);
407	    }
408	    onToggle();
409	  };
410	  const urgency = getUrgencyInfo(task.dueDate);
411	  const queryClient = useQueryClient();
412	  const { toast } = useToast();
413	  const updateTask = useUpdateTask();
414	
415	  const onUpdateCompletedAt = (dateStr: string) => {
416	    if (!dateStr) return;
417	    updateTask.mutate(
418	      { showId, taskId: task.id, data: { completedAt: new Date(dateStr).toISOString() } as any },
419	      {
420	        onSuccess: () => {
421	          toast({ title: "Completion date updated" });
422	          setDatePickerOpen(false);
423	          queryClient.invalidateQueries({ queryKey: getListTasksQueryKey(showId) });
424	        },
425	        onError: () => toast({ title: "Error updating date", variant: "destructive" }),
426	      }
427	    );
428	  };
429	
430	  const form = useForm<z.infer<typeof editTaskSchema>>({
431	    resolver: zodResolver(editTaskSchema),
432	    defaultValues: {
433	      name: task.name,
434	      category: task.category ?? "",
435	      dueDate: task.dueDate ? String(task.dueDate).split("T")[0] : "",
436	      dueDateRule: task.dueDateRule ?? "",
437	      notes: task.notes ?? "",
438	    },
439	  });
440	
441	  const openEdit = () => {
442	    form.reset({
443	      name: task.name,
444	      category: task.category ?? "",
445	      dueDate: task.dueDate ? String(task.dueDate).split("T")[0] : "",
446	      dueDateRule: task.dueDateRule ?? "",
447	      notes: task.notes ?? "",
448	    });
449	    setEditOpen(true);
450	  };
451	
452	  const onEditSubmit = (data: z.infer<typeof editTaskSchema>) => {
453	    updateTask.mutate(
454	      { showId, taskId: task.id, data },
455	      {
456	        onSuccess: () => {
457	          toast({ title: "Task updated" });
458	          setEditOpen(false);
459	          queryClient.invalidateQueries({ queryKey: getListTasksQueryKey(showId) });
460	          queryClient.invalidateQueries({ queryKey: getGetShowQueryKey(showId) });
461	        },
462	        onError: () => toast({ title: "Error updating task", variant: "destructive" }),
463	      }
464	    );
465	  };
466	
467	  return (
468	    <div className={`group flex flex-col p-3 rounded-lg border bg-card transition-all duration-300 ${justCompleted ? 'border-green-500/60 bg-green-500/8 scale-[1.01]' : task.completed ? 'opacity-60' : 'hover:border-primary/30'}`}>
469	      <div className="flex items-start gap-3">
470	        <div className={`mt-1 transition-transform duration-150 ${justCompleted ? 'scale-125' : 'scale-100'}`}>
471	          <Checkbox
472	            checked={task.completed}
473	            onCheckedChange={handleToggle}
474	            className={`transition-colors duration-300 ${task.completed ? 'data-[state=checked]:bg-green-500 data-[state=checked]:text-white border-green-500' : ''}`}
475	          />
476	        </div>
477	
478	        <div className="flex-1 min-w-0">
479	          <div className="flex flex-wrap items-center gap-2">
480	            <span className={`relative font-medium transition-colors duration-500 ${task.completed ? 'text-muted-foreground' : ''}`}>
481	              {task.name}
482	              <span
483	                className={`absolute inset-y-0 left-0 flex items-center pointer-events-none ${justCompleted ? 'animate-strikethrough' : ''}`}
484	                aria-hidden="true"
485	                style={{ width: justCompleted ? undefined : task.completed ? '100%' : '0%' }}
486	              >
487	                <span className="block w-full h-px bg-current opacity-60" />
488	              </span>
489	            </span>
490	            {task.category && (
491	              <Badge variant="outline" className={`${getCategoryColor(task.category)} border-transparent text-xs py-0 h-5`}>
492	                {task.category}
493	              </Badge>
494	            )}
495	            {task.notes && !expanded && (
496	              <Button variant="ghost" size="icon" className="h-5 w-5 text-muted-foreground" onClick={() => setExpanded(true)}>
497	                <MessageSquare className="h-3 w-3" />
498	              </Button>
499	            )}
500	          </div>
501	
502	          <div className="flex flex-wrap items-center gap-3 mt-1.5 text-xs">
503	            {task.completed && task.completedAt ? (
504	              <Popover open={datePickerOpen} onOpenChange={setDatePickerOpen}>
505	                <PopoverTrigger asChild>
506	                  <button className="flex items-center gap-1 font-medium text-green-500 hover:text-green-400 hover:underline cursor-pointer">
507	                    <CheckCircle2 className="h-3 w-3" />
508	                    Done {format(new Date(task.completedAt), "MMM d, yyyy")}
509	                  </button>
510	                </PopoverTrigger>
511	                <PopoverContent className="w-auto p-3" align="start">
512	                  <p className="text-xs text-muted-foreground mb-2">Adjust completion date</p>
513	                  <input
514	                    type="date"
515	                    defaultValue={format(new Date(task.completedAt), "yyyy-MM-dd")}
516	                    className="flex h-9 w-full rounded-md border border-input bg-transparent px-3 py-1 text-sm shadow-sm"
517	                    onChange={(e) => onUpdateCompletedAt(e.target.value)}
518	                  />
519	                </PopoverContent>
520	              </Popover>
